public interface AreaCalculable {
    public double area();
}

public interface VolumeCalculable extends AreaCalculable {
    public double volume();
}

public class Circle implements AreaCalculable {
    @Override
    public double area() {
        return Math.PI * radius * radius;
    }
}

public class Square implements AreaCalculable {
    @Override
    public double area() {
        return length * length;
    }
}
